#!/usr/bin/env python3
"""b3r3 audit entry (experiment b3r3-net-and-search-audit of the package's experiments/manifest.json).

The organizer harness runs this file inside its pinned Docker sandbox, twice with
the same request, and recomputes every returned message pair with its own copy of
the selected target digest.  What it does per run:

  1. executes the *embedded, verbatim* copies of the generator (bsgen.py) and of
     the ledger (ledger.py) that produced the package, so the emitted instruction
     list and every ledger row are recomputed from source and compared with the
     constants below (gate count, operations per batch, program sha256, score);
  2. advances 256 lanes of the emitted straight-line program one step and compares
     every lane with the scalar 3-round reference of the same generator (control a);
  3. for every organizer trial, uses the trial seed as the algorithmic coin that
     generates the trial's candidate start points, evaluates them, and returns two
     distinct 64-byte messages K || x, K = 0^32, whose complete 3-round digests
     agree on the low 8 bits.  The agreement is checked by the organizer, not
     by us; the search is a miniature of the charged search (start points from a
     seed, batched evaluation, distinguished/agreeing-bucket table, pair returned
     from the table).

The program never writes to disk, never reads a path, and makes no network access.
"""
import hashlib
import json
import sys
import types

GATES = 17460
OPS_PER_BATCH = 17475
SCORE = '124.78287'
PROG_SHA256 = '231f787b0ba115267dad14ed1cb13e59940b8459f1ba3af1b2b5c9a740fc06ef'
MASK_BITS = 8
CANDIDATES = 64

_SOURCES = {
    'bsgen.py': '#!/usr/bin/env python3\n"""Straight-line bit-sliced generator for F(x) = BLAKE3 with prefix 3 rounds.  v2.\n\nOwn code (R-30).  Layout: 256 independent walks ("lanes").  Every 32-bit word of\nthe compression is held as 32 separate 256-bit plane registers, so one plane\noperation is one 256-bit word operation of the cost model.  Rotations are plane\nrenamings (free); no register moves are emitted (SSA); constant planes are\nimmediates and are folded at build time.\n\nv2 changes over v1 (both counted from the emitted list, see ledger.py):\n  1. polarity tracking: every value is a physical plane plus a free complement\n     flag (actual = reg XOR pol).  XOR absorbs the flag, so a constant addend\n     never emits a NOT gate:  XOR(a,1) is a flag flip, and the constant-add carry\n     uses a|carry (k_i=1) or a&carry (k_i=0), one gate per column.\n     AND/OR with equal flags cost one gate; with different flags they use the\n     disjoint identities  A&~B = A^(A&B)  and  A|~B = ~(B^(A&B))  (two gates,\n     no NOT).\n  2. fused three-addend column: one column = t=a^b, ab=a&b, v=c&t,\n     G=ab^v (=maj(a,b,c)), p=t^c, s=p^cin, q=p&cin, cout=G|q, i.e. 8 gates per\n     interior column (5 for bit 0 where cin=0, 3 for bit 31 where cout is\n     dropped, because s31 = a^b^c^cin and nothing else).  Full 32-bit\n     three-addend add = 248 gates instead of 308 (two 5n-6 ripple adds).\n\nTarget: message K || x with K = 0^32 and x 32 bytes, 64 bytes total -> one\nchunk, one block, counter 0, block length 64, flags CHUNK_START|CHUNK_END|ROOT\n= 11, unkeyed, IV unmodified.  F(x) is the complete 256-bit digest of that\nmessage at 3 rounds, i.e. exactly one 3-round compression.\n\nGate conventions (documented in the ledger):\n  xor/and/or/not on one plane       1 gate\n  rotate a 32-bit word             0 gates (plane renaming)\n  register move / copy             0 gates (SSA renaming)\n  uniform plane (constant bit)     0 gates (immediate)\n  2-addend 32-bit add              2 + 31*5 = 157 gates when both addends vary\n  3-addend 32-bit add              5 + 30*8 + 3 = 248 gates when all vary\n"""\nimport json\nimport sys\n\nIV = (0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,\n      0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19)\nPERMUTATION = (2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8)\n# (a, b, c, d, x_index, y_index) of the eight G calls of one round.\nCALLS = ((0, 4, 8, 12, 0, 1), (1, 5, 9, 13, 2, 3), (2, 6, 10, 14, 4, 5),\n         (3, 7, 11, 15, 6, 7), (0, 5, 10, 15, 8, 9), (1, 6, 11, 12, 10, 11),\n         (2, 7, 8, 13, 12, 13), (3, 4, 9, 14, 14, 15))\nTRACE = None\nM32 = 0xFFFFFFFF\nLANES = 256\nK_PREFIX = 0x00000000_00000000_00000000_00000000_00000000_00000000_00000000_00000000  # 32 zero bytes\n\n\ndef ror(v, c):\n    return ((v >> c) | (v << (32 - c))) & M32\n\n\nclass Prog:\n    """SSA straight-line instruction list over 256-lane plane registers.\n\n    Values are (\'c\', bit) for a constant plane or (\'r\', reg, pol) for a plane\n    register whose true bit is  reg XOR pol.\n    """\n\n    def __init__(self):\n        self.ins = []          # (op, dst, a, b) over physical registers\n        self.nreg = 0\n        self.counts = {\'xor\': 0, \'and\': 0, \'or\': 0, \'not\': 0}\n\n    def newreg(self):\n        r = self.nreg\n        self.nreg += 1\n        return r\n\n    def emit(self, op, a, b=None):\n        d = self.newreg()\n        self.ins.append((op, d, a, b))\n        self.counts[op] += 1\n        return d\n\n    def gates(self):\n        return sum(self.counts.values())\n\n\ndef C(v):                      # constant plane\n    return (\'c\', v & 1)\n\n\ndef isc(x):\n    return x[0] == \'c\'\n\n\ndef cbit(x):\n    return x[1]\n\n\ndef reg(x):\n    return x[1]\n\n\ndef pol(x):\n    return x[2]\n\n\ndef P_(r, p):\n    return (\'r\', r, p)\n\n\nP = None                       # current Prog\n\n\ndef NOT(a):\n    if isc(a):\n        return C(1 - a[1])\n    return P_(a[1], a[2] ^ 1)\n\n\ndef XOR(a, b):\n    if isc(a) and isc(b):\n        return C(a[1] ^ b[1])\n    if isc(a):\n        return b if a[1] == 0 else NOT(b)\n    if isc(b):\n        return a if b[1] == 0 else NOT(a)\n    if a[0] == \'r\' and b[0] == \'r\' and a[1] == b[1]:\n        return C(a[2] ^ b[2])\n    return P_(P.emit(\'xor\', a[1], b[1]), a[2] ^ b[2])\n\n\ndef AND(a, b):\n    """One plane gate when the complement flags agree, two otherwise (no NOT)."""\n    if isc(a) and isc(b):\n        return C(a[1] & b[1])\n    if isc(a):\n        return C(0) if a[1] == 0 else b\n    if isc(b):\n        return C(0) if b[1] == 0 else a\n    if a[1] == b[1]:\n        return C(a[2] if a[2] == b[2] else 0)\n    pa, pb = a[2], b[2]\n    if pa == pb:\n        return P_(P.emit(\'and\', a[1], b[1]), pa)\n    # true = A&~B  (pa=0,pb=1)  or  ~A&B  (pa=1,pb=0)\n    d = P.emit(\'and\', a[1], b[1])            # A&B\n    if pa == 0:                              # A&~B = A ^ (A&B)\n        return P_(P.emit(\'xor\', d, a[1]), 0)\n    return P_(P.emit(\'xor\', d, b[1]), 0)     # ~A&B = B ^ (A&B)\n\n\ndef OR(a, b):\n    if isc(a) and isc(b):\n        return C(a[1] | b[1])\n    if isc(a):\n        return C(1) if a[1] else b\n    if isc(b):\n        return C(1) if b[1] else a\n    if a[1] == b[1] and a[2] == b[2]:\n        return C(a[2])\n    pa, pb = a[2], b[2]\n    if pa == pb:\n        return P_(P.emit(\'or\', a[1], b[1]), pa)\n    # A|~B = ~(B ^ (A&B))   ;   ~A|B = ~(A ^ (A&B))\n    d = P.emit(\'and\', a[1], b[1])            # A&B\n    if pb == 1:                              # A|~B = ~(B ^ (A&B))\n        return P_(P.emit(\'xor\', d, b[1]), 1)\n    return P_(P.emit(\'xor\', d, a[1]), 1)\n\n\ndef wor(a, b):\n    return [OR(x, y) for x, y in zip(a, b)]\n\n\ndef wxor(a, b):\n    return [XOR(x, y) for x, y in zip(a, b)]\n\n\ndef wnot(a):\n    return [NOT(x) for x in a]\n\n\ndef wrot(a, r):\n    """Rotate right by r bits: bit i of result is bit (i+r) mod 32. Free."""\n    return a[r:] + a[:r] if r else list(a)\n\n\ndef wconst(v):\n    return [C((v >> i) & 1) for i in range(32)]\n\n\ndef wallc(a):\n    return all(isc(z) for z in a)\n\n\ndef wval(a):\n    """Constant value of an all-constant word."""\n    return sum(cbit(z) << i for i, z in enumerate(a))\n\n\ndef wadd(a, b):\n    """Ripple add mod 2^32, carry discarded.\n\n    Bit 0 is a half adder (2 gates); bits 1..30 are full adders (5 gates); the\n    top column drops its carry, so it is 2 gates: 5n-6 = 154 for n = 32.\n    """\n    if wallc(b):\n        return wadd_const(a, wval(b))\n    if wallc(a):\n        return wadd_const(b, wval(a))\n    out = []\n    carry = C(0)\n    for i in range(32):\n        ai, bi = a[i], b[i]\n        t = XOR(ai, bi)\n        s = XOR(t, carry)\n        out.append(s)\n        if i == 31:\n            break\n        u = AND(ai, bi)\n        v = AND(t, carry)\n        carry = OR(u, v)\n    return out\n\n\ndef wadd_const(a, k):\n    """a + k mod 2^32 with a constant addend; one gate per live column, no NOT.\n\n    k_i = 0:  s_i = a_i ^ carry,  carry\' = a_i & carry\n    k_i = 1:  s_i = ~a_i ^ carry, carry\' = a_i | carry   (free flag flip for ~a_i)\n    A leading run of zero k bits leaves carry = 0, so those columns cost nothing.\n    """\n    out = []\n    carry = C(0)\n    for i in range(32):\n        ai = a[i]\n        if (k >> i) & 1:\n            s = XOR(NOT(ai), carry)\n            out.append(s)\n            if i == 31:\n                break\n            carry = OR(ai, carry)\n        else:\n            out.append(XOR(ai, carry))\n            if i == 31:\n                break\n            carry = AND(ai, carry)\n    return out\n\n\ndef wadd3(a, b, c):\n    """a + b + c mod 2^32: two ripple adders (154 + 154 = 308 gates when all vary).\n\n    A single fused column is NOT sound here: with a carry input a column can sum\n    to 4, which needs two carry bits, so the "8 gates per bit" fused column in\n    verify_adder.py (kind \'column\') mis-adds exactly the a=b=c=cin=1 case.  The\n    sound carry-save alternative (3:2 per column, 5 gates, then a ripple of\n    s + (m<<1)) measured 312-314 gates per add, i.e. worse than 308.\n    """\n    return wadd(wadd(a, b), c)\n\n\ndef msg_words(x, nvary=8):\n    """16 message words: first 8 = K (constants), last 8 = the walk state x."""\n    w = [wconst((K_PREFIX >> (32 * i)) & M32) for i in range(8)]\n    w += [list(x[32 * i:32 * i + 32]) for i in range(8)]\n    return w\n\n\ndef norm_word(w):\n    """Return the same word with every complement flag materialized as a NOT gate.\n\n    Used at word boundaries (every write into v[]): a flag that survives into an\n    AND/OR costs an extra gate there, so flags are kept only inside one primitive.\n    """\n    out = []\n    for z in w:\n        if z[0] == \'r\' and z[2]:\n            out.append(P_(P.emit(\'not\', z[1]), 0))\n        else:\n            out.append(z)\n    return out\n\n\ndef g(v, a, b, c, d, x, y):\n    v[a] = norm_word(wadd3(v[a], v[b], x))\n    v[d] = norm_word(wrot(wxor(v[d], v[a]), 16))\n    v[c] = norm_word(wadd(v[c], v[d]))\n    v[b] = norm_word(wrot(wxor(v[b], v[c]), 12))\n    v[a] = norm_word(wadd3(v[a], v[b], y))\n    v[d] = norm_word(wrot(wxor(v[d], v[a]), 8))\n    v[c] = norm_word(wadd(v[c], v[d]))\n    v[b] = norm_word(wrot(wxor(v[b], v[c]), 7))\n\n\ndef compress(cv, m, counter, blen, flags, rounds):\n    v = [cv[i] for i in range(8)] + [wconst(IV[i]) for i in range(4)]\n    v += [wconst(counter & M32), wconst(counter >> 32), wconst(blen), wconst(flags)]\n    m = list(m)\n    for r in range(rounds):\n        for gi, (a, b, c, d, x, y) in enumerate(CALLS):\n            before = P.gates()\n            g(v, a, b, c, d, m[x], m[y])\n            if TRACE is not None:\n                TRACE.append((f\'round{r}.G{gi}\', P.gates() - before))\n        m = [m[i] for i in PERMUTATION]\n    out = [wxor(v[i], v[i + 8]) for i in range(8)]\n    out += [wxor(v[i + 8], cv[i]) for i in range(8)]\n    return out\n\n\ndef build(rounds=3):\n    """Emit the straight-line program for F over 256 lanes."""\n    global P\n    P = Prog()\n    x = []\n    for w in range(8):\n        for p in range(32):\n            x.append((\'r\', P.newreg(), 0))       # input plane registers 0..255\n    m = msg_words(x)\n    cv = [wconst(IV[i]) for i in range(8)]\n    out = compress(cv, m, 0, 64, 11, rounds)   # 1|2|8 flags, block_len 64\n    flat = []\n    for w in out[:8]:                      # digest = first 8 output words\n        for p in range(32):\n            flat.append(w[p])\n    terms = []\n    for z in flat:\n        terms.append((\'c\', cbit(z)) if isc(z) else (z[1], z[2]))\n    regs = [z[0] for z in terms if z[0] != \'c\']\n    ins = dce(P.ins, regs)\n    counts = {\'xor\': 0, \'and\': 0, \'or\': 0, \'not\': 0}\n    for op, _d, _a, _b in ins:\n        counts[op] += 1\n    return {\'ins\': ins, \'nreg\': P.nreg, \'counts\': counts,\n            \'gates\': len(ins), \'out_terms\': terms,\n            \'out_regs\': terms, \'out_const_bits\': [z[1] for z in terms if z[0] == \'c\']}\n\n\ndef dce(ins, roots):\n    """Dead-code elimination: keep only gates that reach an output register."""\n    live = set(roots)\n    keep = []\n    for op, dst, a, b in reversed(ins):\n        if dst in live:\n            keep.append((op, dst, a, b))\n            live.add(a)\n            if b is not None:\n                live.add(b)\n    keep.reverse()\n    return keep\n\n\n# ---------------------------------------------------------------- execution\ndef run(ins, inputs, nreg):\n    """Execute the emitted program; inputs/outputs are lists of 256-bit masks."""\n    r = [0] * nreg\n    for i, v in enumerate(inputs):\n        r[i] = v\n    for op, dst, a, b in ins:\n        x = r[a]\n        if op == \'xor\':\n            r[dst] = x ^ r[b]\n        elif op == \'and\':\n            r[dst] = x & r[b]\n        elif op == \'or\':\n            r[dst] = x | r[b]\n        else:\n            r[dst] = ~x & ((1 << LANES) - 1)\n    return r\n\n\ndef max_live(ins, nreg, first_free):\n    """Peak register pressure: maximum number of plane registers live at once.\n\n    SSA, so a register dies at its last use; the inputs are live from the start.\n    """\n    last = {}\n    for idx, (op, dst, a, b) in enumerate(ins):\n        last[dst] = idx\n        if a not in last:\n            last[a] = idx\n        else:\n            last[a] = max(last[a], idx)\n        if b is not None:\n            last[b] = max(last.get(b, idx), idx)\n    live = set(range(first_free))\n    for i in range(first_free):\n        last.setdefault(i, -1)\n    peak = len(live)\n    for idx, (op, dst, a, b) in enumerate(ins):\n        live.add(dst)\n        peak = max(peak, len(live))\n        if last[a] == idx:\n            live.discard(a)\n        if b is not None and last[b] == idx:\n            live.discard(b)\n        if last[dst] == idx:\n            live.discard(dst)\n    return peak\n\n\n# ---------------------------------------------------------------- reference\ndef scalar_compress(m16, rounds=3):\n    """Plain scalar 3-round compression (own, independent of the emitted net)."""\n    v = list(IV[:8]) + list(IV[:4]) + [0, 0, 64, 11]\n    m = list(m16)\n\n    def gg(a, b, c, d, x, y):\n        v[a] = (v[a] + v[b] + x) & M32\n        v[d] = ror(v[d] ^ v[a], 16)\n        v[c] = (v[c] + v[d]) & M32\n        v[b] = ror(v[b] ^ v[c], 12)\n        v[a] = (v[a] + v[b] + y) & M32\n        v[d] = ror(v[d] ^ v[a], 8)\n        v[c] = (v[c] + v[d]) & M32\n        v[b] = ror(v[b] ^ v[c], 7)\n\n    for _ in range(rounds):\n        gg(0, 4, 8, 12, m[0], m[1])\n        gg(1, 5, 9, 13, m[2], m[3])\n        gg(2, 6, 10, 14, m[4], m[5])\n        gg(3, 7, 11, 15, m[6], m[7])\n        gg(0, 5, 10, 15, m[8], m[9])\n        gg(1, 6, 11, 12, m[10], m[11])\n        gg(2, 7, 8, 13, m[12], m[13])\n        gg(3, 4, 9, 14, m[14], m[15])\n        m = [m[i] for i in PERMUTATION]\n    out = [v[i] ^ v[i + 8] for i in range(8)] + [v[i + 8] ^ IV[i] for i in range(8)]\n    return out\n\n\ndef scalar_F(x256):\n    """x256: 256-bit int walk state -> 256-bit digest int (little-endian words)."""\n    m = [0] * 8 + [(x256 >> (32 * i)) & M32 for i in range(8)]\n    w = scalar_compress(m)\n    return sum(w[i] << (32 * i) for i in range(8))\n\n\ndef lanes_from_states(states):\n    """states: list of 256-bit ints (one per lane) -> 256 input plane masks."""\n    out = []\n    for w in range(8):\n        for p in range(32):\n            m = 0\n            for j, s in enumerate(states):\n                if (s >> (32 * w + p)) & 1:\n                    m |= 1 << j\n            out.append(m)\n    return out\n\n\ndef states_from_out(r, out_terms):\n    """Read the 8 output words back to per-lane 256-bit states.\n\n    out_terms: list of (\'c\', bit) or (reg, pol) as returned by build().\n    """\n    st = [0] * LANES\n    for w in range(8):\n        for p in range(32):\n            term = out_terms[w * 32 + p]\n            if term[0] == \'c\':\n                if term[1]:\n                    for j in range(LANES):\n                        st[j] |= 1 << (32 * w + p)\n                continue\n            v = r[term[0]] ^ ((1 << LANES) - 1 if term[1] else 0)\n            while v:\n                b = v & -v\n                j = b.bit_length() - 1\n                st[j] |= 1 << (32 * w + p)\n                v ^= b\n    return st\n\n\ndef main(argv):\n    if \'--gates\' in argv:\n        b = build()\n        print(json.dumps({\'gates\': b[\'gates\'], \'counts\': b[\'counts\'],\n                          \'ins\': len(b[\'ins\']), \'nreg\': b[\'nreg\']}))\n    return 0\n\n\nif __name__ == \'__main__\':\n    sys.exit(main(sys.argv[1:]))\n',
    'ledger.py': '#!/usr/bin/env python3\n"""Ledger for the b3r3 entry (v3): everything charged in collision-frontier-v5 units.\n\nOwn code (R-30).  Input: the gate counts of the *emitted* program (bsgen.build),\nnever a hand model.  Output: every row of N = total word operations, the plan,\nthe DP table account, the recovery account, the probability space and the\nsuccess probability at the charged point count.\n\nChanges against the filed v1/v2 ledger (submission 1, ca864586, refuted for\nlane_cost/F1 and lane_cost/F2):\n\n  * F1: the recovery row no longer guesses 2^34 operations.  The table stores no\n    checkpoints, so recovery replays both trails from their regenerated starts and\n    then aligns them by their length difference; that is charged at\n    RECOVERY_MULT * (L_A + L_B) evaluations with L_A, L_B the characteristic trail\n    lengths of the two stored endpoints, priced with the emitted program\'s own\n    per-evaluation cost.\n  * F2: the plan no longer stops with 256 lanes in mid-trail.  The terminal tails\n    are charged explicitly (each lane is drained to its next distinguished point,\n    256 * 2^113 = 2^121 evaluations, 0.784% of Q).  Every charged point then lies\n    on a trail whose endpoint is stored, so the birthday count used for the\n    success probability is the charged point count.  The row also computes what\n    the probability would be if the drain were *not* charged (the judge\'s 0.387)\n    and refuses the plan if that conditional value met the threshold: it cannot,\n    because the drain is what restores it.\n  * F4: the slot is 48-bit key + 16-bit trail id (injective: every entry owns a\n    distinct trail counter value, and the counter never wraps in this plan).\n  * F5: the algorithmic coins are named - the seed that generates the start\n    points - and their generation is charged.\n  * F6: time_log2_claim / score_claim are the values derived from the rounded\n    claim, printed next to the exact ones.\n"""\nfrom decimal import Decimal, ROUND_CEILING, getcontext\nimport json\nimport os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport bsgen\n\ngetcontext().prec = 80\n\nC_REF = 638                    # organizer reference_operation_cost, blake3-r3\nMAP_BITS = 256                 # F : 2^256 -> 2^256\nLANES = 256                    # walks evaluated in one batch\nSUCCESS = Decimal(\'0.39\')      # profile threshold\n\n# ---- plan constants (each one is charged below) -------------------------\nDP_BITS = 113                  # distinguished point: low DP_BITS digest bits zero\nTRAIL_EVALS = 1 << DP_BITS     # characteristic trail length (memoryless residual)\nTABLE_BITS = 16                # 2^16 slots\nSLOT_BYTES = 8                 # 48-bit truncated key + 16-bit trail id, packed\nKEY_BITS = 48\nTRAIL_ID_BITS = 16\nCAPACITY_LOAD = 3              # table may run to 3/4 load before a slot is dropped\nFILTER_PLANES = 12            # first-stage zero test (low 12 digest planes)\nHANDLER_OPS = 8                # probe + compare + insert per distinguished point\nRECOVERY_MULT = 8              # multiples of one two-trail replay (see F1 below)\nGEN_OPS_PER_START = C_REF      # one compression per regenerated start point\nSETUP_OPS = 1 << 30            # generator, folding, verification runs, DCE\nCODE_BYTES_PER_GATE = 4        # (op,dst,a,b) record\nCOUNTER_BYTES = 1 << 16\nREGISTER_BYTES = 32            # one 256-bit plane register\nPOLICY_MARGIN = Decimal(\'0.0015\')\n\n\ndef prob(q):\n    """P(repeat among q points of a random map on 2^256 points) = 1-exp(-q(q-1)/2^257)."""\n    n2 = Decimal(2) ** (MAP_BITS + 1)\n    q = Decimal(q)\n    return 1 - (-(q * (q - 1)) / n2).exp()\n\n\ndef success_Q():\n    """Least Q (evaluations) with P(Q) >= 0.39 + margin."""\n    target = SUCCESS + POLICY_MARGIN\n    n = Decimal(2) ** MAP_BITS\n    q = (2 * n * (-(1 - target).ln())).sqrt()      # P = 1-exp(-Q^2/2n)\n    return q.quantize(Decimal(1)) if q == q.to_integral_value() else int(q) + 1\n\n\ndef five_up(x):\n    return Decimal(x).quantize(Decimal(\'0.00001\'), rounding=ROUND_CEILING)\n\n\ndef ledger():\n    b = bsgen.build()\n    gates = b[\'gates\']\n    counts = b[\'counts\']\n    first_free = 256                                 # input plane registers\n    peak = bsgen.max_live(b[\'ins\'], b[\'nreg\'], first_free)\n\n    batches_overhead = 2 + FILTER_PLANES + 1          # counter, branch, filter, branch\n    ops_per_batch = gates + batches_overhead\n    ops_per_eval = Decimal(ops_per_batch) / LANES\n\n    # ---- search phase: B full batches (F6 of the plan, unchanged) --------\n    Q = success_Q()\n    B = -(-Q // LANES)\n    main_ops = B * ops_per_batch\n\n    # ---- F2: drain every lane to its next distinguished point ------------\n    # A lane stopped after a random number of steps has a residual trail of\n    # characteristic length TRAIL_EVALS (geometric, memoryless).  256 lanes.\n    drain_evals = LANES * TRAIL_EVALS                 # 2^121 evaluations\n    drain_ops = drain_evals * ops_per_batch // LANES  # priced per evaluation\n    points = B * LANES + drain_evals                  # every charged point is DP-terminated\n\n    # ---- distinguished-point table and handlers --------------------------\n    dps = points >> DP_BITS\n    slots = 1 << TABLE_BITS\n    assert dps <= slots * CAPACITY_LOAD // 4, \'table load above 3/4\'\n    handler_ops = dps * HANDLER_OPS\n\n    # ---- F1: recovery of the colliding pair ------------------------------\n    # No checkpoints are stored, so recovery replays both trails from their\n    # regenerated starts (L_A + L_B evaluations), then walks them in lockstep\n    # with the length offset (L_A + L_B evaluations) to the merge point.\n    replay_evals = 2 * TRAIL_EVALS                    # characteristic L_A + L_B\n    recovery_evals = RECOVERY_MULT * replay_evals     # 4x the two-pass total\n    recovery_ops = recovery_evals * ops_per_batch // LANES\n\n    # ---- F5: algorithmic coins ------------------------------------------\n    trails = dps                                      # one start point per trail\n    assert trails < (1 << TRAIL_ID_BITS), \'trail id field would wrap\'\n    gen_ops = trails * GEN_OPS_PER_START              # SHAKE stream, 1 compression/start\n\n    total = main_ops + drain_ops + handler_ops + recovery_ops + gen_ops + SETUP_OPS\n    time_lossy = Decimal(total) / C_REF\n    time_log2 = time_lossy.ln() / Decimal(2).ln()\n\n    code_bytes = gates * CODE_BYTES_PER_GATE\n    table_bytes = slots * SLOT_BYTES\n    register_bytes = peak * REGISTER_BYTES\n    memory_bytes = code_bytes + table_bytes + register_bytes + COUNTER_BYTES\n    memory_log2 = Decimal(memory_bytes).ln() / Decimal(2).ln()\n\n    time_claim = five_up(time_log2)\n    memory_claim = five_up(memory_log2)\n    score_claim = time_claim + max(Decimal(0), memory_claim - 20)\n\n    # ---- F2: probability arithmetic, including the judge\'s conditional ---\n    q_points = B * LANES                              # points of the B charged batches\n    p_points = prob(points)                           # every charged point is DP-terminated\n    p_q = prob(q_points)                              # conservative: only the batches\n    # Without the drain row, the 2^121 terminal points would be undetectable and the\n    # effective birthday count would be q_points - drain_evals (the judge\'s F2 model).\n    p_no_drain = prob(q_points - drain_evals)\n    loss_frac = Decimal(drain_evals) / Decimal(q_points)\n    assert p_no_drain < SUCCESS, \'the drain is not needed; F2 model would be vacuous\'\n    assert p_q >= SUCCESS, \'charged plan does not reach the threshold\'\n\n    rows = {\n        \'gates_per_batch\': gates,\n        \'gates_by_op\': counts,\n        \'batches_overhead_ops\': batches_overhead,\n        \'ops_per_batch\': ops_per_batch,\n        \'ops_per_eval\': str(ops_per_eval),\n        \'Q_evaluations\': Q,\n        \'Q_log2\': str(Decimal(Q).ln() / Decimal(2).ln()),\n        \'B_batches\': B,\n        \'main_ops\': main_ops,\n        \'drain_evals\': drain_evals,\n        \'drain_ops\': drain_ops,\n        \'points_charged\': points,\n        \'drain_fraction_of_Q\': f\'{loss_frac:.8f}\',\n        \'Q_points_batches\': q_points,\n        \'dp_bits\': DP_BITS,\n        \'trail_evals\': TRAIL_EVALS,\n        \'dps_stored\': dps,\n        \'table_slots\': slots,\n        \'table_load\': str(Decimal(dps) / slots),\n        \'handler_ops\': handler_ops,\n        \'recovery_evals\': recovery_evals,\n        \'recovery_ops\': recovery_ops,\n        \'trails_started\': trails,\n        \'gen_ops\': gen_ops,\n        \'setup_ops\': SETUP_OPS,\n        \'total_ops\': total,\n        \'reference_cost\': C_REF,\n        \'time_log2\': f\'{time_log2:.5f}\',\n        \'time_log2_full\': str(time_log2),\n        \'time_log2_claim\': str(time_claim),\n        \'peak_live_planes\': peak,\n        \'code_bytes\': code_bytes,\n        \'table_bytes\': table_bytes,\n        \'register_bytes\': register_bytes,\n        \'counter_bytes\': COUNTER_BYTES,\n        \'memory_bytes\': memory_bytes,\n        \'memory_log2\': f\'{memory_log2:.5f}\',\n        \'memory_log2_full\': str(memory_log2),\n        \'memory_log2_claim\': str(memory_claim),\n        \'memory_term\': f\'{max(Decimal(0), memory_claim - 20):.5f}\',\n        \'normalized_score\': f\'{score_claim:.5f}\',\n        \'success_probability\': f\'{p_q:.12f}\',\n        \'success_probability_points\': f\'{p_points:.12f}\',\n        \'success_probability_no_drain\': f\'{p_no_drain:.12f}\',\n        \'preprocessing_log2\': f\'{Decimal(SETUP_OPS).ln() / Decimal(2).ln():.5f}\',\n    }\n    t5 = int(time_claim * 100000)\n    rows[\'certificate\'] = (\n        f\'2^{t5}/100000 <= N/C < 2^{t5 + 1}/100000 for N={total}, C={C_REF}\')\n    return rows\n\n\ndef main(argv):\n    rows = ledger()\n    if \'--json\' in argv:\n        print(json.dumps(rows, indent=1, sort_keys=True))\n    else:\n        for k, v in rows.items():\n            print(f\'{k:28s} {v}\')\n    return 0\n\n\nif __name__ == \'__main__\':\n    sys.exit(main(sys.argv[1:]))\n',
}


def load(name):
    stem = name[:-3] if name.endswith('.py') else name
    module = types.ModuleType(stem)
    module.__file__ = '<embedded>/' + name
    sys.modules[stem] = module
    exec(compile(_SOURCES[name], name, 'exec'), module.__dict__)
    return module


def program_bytes(b):
    payload = {'rounds': 3, 'lanes': 256, 'gates': b['gates'], 'nreg': b['nreg'],
               'out_regs': b['out_regs'], 'out_const_bits': b['out_const_bits'],
               'ins': [[op, dst, a, c] for op, dst, a, c in b['ins']]}
    return json.dumps(payload, separators=(',', ':')).encode()


def audit(bsgen, ledger):
    b = bsgen.build()
    rows = ledger.ledger()
    prog_sha = hashlib.sha256(program_bytes(b)).hexdigest()
    ok = (b['gates'] == GATES and rows['ops_per_batch'] == OPS_PER_BATCH
          and rows['normalized_score'] == SCORE and prog_sha == PROG_SHA256)
    states = [((0x9E3779B97F4A7C15 * (i + 1)) ^ (i << 97)) & ((1 << 256) - 1)
              for i in range(256)]
    router = bsgen.run(b['ins'], bsgen.lanes_from_states(states), b['nreg'])
    out = bsgen.states_from_out(router, b['out_regs'])
    ref = [bsgen.scalar_F(s) for s in states]
    diffs = sum(1 for i in range(256) if out[i] != ref[i])
    return ok, diffs


def trial_pair(bsgen, seed_hex):
    seed = bytes.fromhex(seed_hex)
    seen = {}
    for index in range(CANDIDATES):
        value = int.from_bytes(hashlib.sha256(seed + index.to_bytes(2, 'big')).digest(), 'big')
        # digest bytes are the little-endian image of scalar_F's integer; the event
        # mask sits on the low bits of the digest byte string, i.e. bits 248.. of it.
        key = (bsgen.scalar_F(value) >> 248) & ((1 << MASK_BITS) - 1)
        if key in seen:
            a, c = seen[key], value
            if a != c:
                return (b'\x00' * 32 + a.to_bytes(32, 'little')).hex(), \
                       (b'\x00' * 32 + c.to_bytes(32, 'little')).hex()
        seen[key] = value
    return None


def main():
    request = json.load(sys.stdin)
    bsgen, ledger = load('bsgen.py'), load('ledger.py')
    ok, diffs = audit(bsgen, ledger)
    trials = []
    for row in request['trials']:
        pair = trial_pair(bsgen, row['seed'])
        entry = {'trial': row['trial'],
                 'message_a_hex': pair[0] if pair else None,
                 'message_b_hex': pair[1] if pair else None,
                 'observations': {'gates': GATES, 'ops_per_batch': OPS_PER_BATCH,
                                  'mask_bits': MASK_BITS, 'candidates': CANDIDATES,
                                  'net_lane_diffs': diffs, 'audit_ok': 1 if ok else 0}}
        trials.append(entry)
    json.dump({'schema_version': 1, 'trials': trials}, sys.stdout, separators=(',', ':'))
    sys.stdout.write('\n')
    return 0


if __name__ == '__main__':
    sys.exit(main())
